// 由 build.js 生成，请勿手改。修改结构请编辑 map-source.js。
window.AIIO_MAP = {"en":"NCA-AIIO","zh":"AI 基础设施与运维认证","c":[{"en":"Essential AI Knowledge","zh":"AI 基础知识","c":[{"en":"AI Concepts","zh":"AI 概念","c":[{"en":"AI ⊃ ML ⊃ DL","zh":"AI、ML、DL 的包含关系","k":"ai-basics","ce":"How are AI, ML, and DL related?","cz":"AI、ML、DL 的包含关系","eb":"AI ⊃ ML ⊃ DL. ML learns patterns from data; DL is ML that uses multi-layer neural networks.","zb":"AI ⊃ ML ⊃ DL。ML 从数据学规律；DL 是用多层神经网络的 ML。"},{"en":"Supervised learning","zh":"监督学习","k":"ai-basics","ce":"Supervised learning","cz":"监督学习","eb":"Training data has labels (input → correct answer). Typical tasks: classification and regression.","zb":"训练数据带标签（输入→正确答案）。典型任务：分类、回归。"},{"en":"Unsupervised learning","zh":"无监督学习","k":"ai-basics","ce":"Unsupervised learning","cz":"无监督学习","eb":"Data has no labels; the model finds structure itself. Typical tasks: clustering, dimensionality reduction, anomaly detection.","zb":"数据没有标签，模型自己发现结构。典型：聚类、降维、异常检测。"},{"en":"Reinforcement learning","zh":"强化学习","k":"ai-basics","ce":"Reinforcement learning","cz":"强化学习","eb":"An agent acts in an environment and learns a policy from reward signals. Used in robotics, games, and RLHF.","zb":"智能体在环境中行动，根据奖励信号学习策略。用于机器人、游戏、RLHF。"},{"en":"Neural network","zh":"神经网络","k":"ai-basics","ce":"Neural network","cz":"神经网络","eb":"A model made of layers of neurons (weighted sum + activation function); its parameters are weights and biases.","zb":"由层层神经元（加权求和 + 激活函数）组成的模型，参数是权重和偏置。"},{"en":"Backpropagation","zh":"反向传播","k":"ai-basics","ce":"Backpropagation","cz":"反向传播","eb":"Uses the chain rule to compute each parameter's gradient from the output layer backward. Core of training; not needed for inference.","zb":"用链式法则从输出层往回计算每个参数的梯度，是训练的核心步骤，推理时不需要。"},{"en":"Transformer","zh":"Transformer","k":"ai-basics","ce":"Transformer","cz":"","eb":"Architecture based on self-attention that processes a whole sequence in parallel. Basis of modern LLMs and ViTs.","zb":"基于自注意力（self-attention）的架构，可并行处理整个序列。现代 LLM、ViT 都基于它。"},{"en":"Self-attention","zh":"自注意力","k":"ai-basics","ce":"Self-attention","cz":"自注意力","eb":"Each token scores its relevance to every other token and takes a weighted sum; compute grows with the square of sequence length.","zb":"序列中每个 token 计算与其他所有 token 的相关性并加权汇总；计算量随序列长度平方增长。"},{"en":"Generative AI","zh":"生成式 AI","k":"ai-basics","ce":"Generative AI","cz":"生成式 AI","eb":"Models that create new content (text, images, code, audio, video), such as LLMs and diffusion models.","zb":"生成新内容（文本、图像、代码、音频、视频）的模型，如 LLM、扩散模型。"},{"en":"Agentic AI","zh":"智能体 AI","k":"ai-basics","ce":"Agentic AI","cz":"智能体 AI","eb":"An LLM combined with planning, tool use, and memory that completes multi-step tasks autonomously.","zb":"LLM 结合规划、工具调用、记忆，能自主多步完成任务。"}]},{"en":"Training vs Inference","zh":"训练与推理","c":[{"en":"Workflow order","zh":"AI 工作流顺序","k":"workflow","ce":"Order of the end-to-end AI workflow","cz":"AI 端到端工作流顺序","eb":"Data preparation (collect/clean/label/ETL) → training → optimization (quantize/prune/TensorRT) → deployment for inference → monitoring and retraining.","zb":"数据准备（采集/清洗/标注/ETL）→ 训练 → 优化（量化/剪枝/TensorRT）→ 部署推理 → 监控与再训练。"},{"en":"Training","zh":"训练","k":"workflow","ce":"Training","cz":"训练","eb":"Forward + backward passes that repeatedly update weights. Huge compute over long periods, usually many GPUs and nodes.","zb":"前向 + 反向传播，反复更新权重。计算量极大、持续时间长，通常多 GPU / 多节点。"},{"en":"Inference","zh":"推理","k":"workflow","ce":"Inference","cz":"推理","eb":"Runs only the forward pass with fixed trained weights to produce predictions. Focus: latency, throughput, cost; runs continuously in production.","zb":"用训练好的固定权重只做前向计算，得到预测。关注延迟、吞吐、成本，长期在线运行。"},{"en":"Hardware priorities","zh":"硬件侧重点","k":"workflow","ce":"Hardware priorities: training vs inference","cz":"训练和推理的硬件侧重点","eb":"Training: max compute, GPU memory, fast inter-node network, fast storage. Inference: latency, throughput per watt, cost, elastic scaling.","zb":"训练：最大算力、显存容量、节点间高速网络、高速存储。推理：延迟、吞吐/瓦、成本、弹性扩缩。"},{"en":"Pretraining","zh":"预训练","k":"workflow","ce":"Pretraining","cz":"预训练","eb":"Training a foundation model from scratch on massive general data; the most expensive stage (thousands of GPUs, weeks to months).","zb":"在海量通用数据上从零训练基础模型，成本最高（成千上万 GPU、数周到数月）。"},{"en":"Fine-tuning","zh":"微调","k":"workflow","ce":"Fine-tuning","cz":"微调","eb":"Continuing to train a pretrained model on domain data to adapt it to a specific task.","zb":"在预训练模型基础上用领域数据继续训练，使其适配特定任务。"},{"en":"Model optimization","zh":"模型优化","k":"workflow","ce":"Model optimization","cz":"模型优化","eb":"Shrinking and speeding up a model before deployment: quantization, pruning, distillation, layer fusion (TensorRT).","zb":"部署前减小模型、提高速度：量化、剪枝、蒸馏、层融合（TensorRT）。"},{"en":"Latency vs throughput","zh":"延迟与吞吐的权衡","k":"workflow","ce":"Latency vs throughput trade-off","cz":"延迟与吞吐的权衡","eb":"Larger batches raise GPU utilization and throughput, but each request waits and computes longer, so latency rises.","zb":"增大 batch 提高 GPU 利用率和吞吐，但单请求等待和计算时间变长，延迟上升。"},{"en":"Checkpoint","zh":"检查点","k":"workflow","ce":"Checkpoint","cz":"检查点","eb":"Periodically saved model weights and optimizer state, so training can resume from the latest checkpoint after an interruption.","zb":"定期保存模型权重和优化器状态，训练中断后可从最近检查点恢复。"},{"en":"MLOps","zh":"MLOps","k":"workflow","ce":"MLOps","cz":"","eb":"Applying DevOps practices to ML: data/model versioning, automated training pipelines, deployment, monitoring.","zb":"把 DevOps 实践用于机器学习：数据和模型版本管理、自动训练流水线、部署、监控。"}]},{"en":"GPU Hardware","zh":"GPU 硬件原理","c":[{"en":"CPU vs GPU","zh":"CPU 与 GPU","k":"gpu-hw","ce":"CPU vs GPU design goals","cz":"CPU 与 GPU 的设计取向","eb":"CPU: few powerful cores, large caches, high clocks; latency-optimized for serial, branch-heavy work. GPU: thousands of simple cores; throughput-optimized for data parallelism.","zb":"CPU：少量强核心、大缓存、高频率，延迟优化，擅长串行和复杂分支。GPU：成千上万简单核心，吞吐优化，擅长数据并行。"},{"en":"Why GPUs for DL","zh":"为什么用 GPU 做深度学习","k":"gpu-hw","ce":"Why GPUs suit deep learning","cz":"为什么 GPU 适合深度学习","eb":"DL is dominated by large matrix multiply-accumulate operations that split into many independent parallel operations; GPUs have many cores and high memory bandwidth.","zb":"深度学习核心是大规模矩阵乘加，可拆成大量独立运算并行执行；GPU 并行核心多、显存带宽高。"},{"en":"Streaming Multiprocessor (SM)","zh":"流式多处理器","k":"gpu-hw","ce":"Streaming Multiprocessor (SM)","cz":"流式多处理器","eb":"The GPU's basic compute unit, containing CUDA cores, Tensor Cores, registers, and shared memory/L1. A GPU has tens to hundreds of SMs.","zb":"GPU 的基本计算单元，内含 CUDA Core、Tensor Core、寄存器、共享内存/L1。GPU 由几十到上百个 SM 组成。"},{"en":"Tensor Core","zh":"张量核心","k":"gpu-hw","ce":"Tensor Core","cz":"张量核心","eb":"Unit dedicated to matrix multiply-accumulate (MMA); introduced with Volta; the main engine of DL acceleration.","zb":"专门执行矩阵乘加（MMA）的单元，Volta 首次引入，深度学习加速的主力。"},{"en":"RT Core (distractor)","zh":"RT Core（干扰项）","k":"gpu-hw","ce":"RT Core","cz":"光线追踪核心","eb":"Ray-tracing unit (since Turing) for graphics rendering; unrelated to AI training — a common distractor.","zb":"光线追踪加速单元（Turing 起），用于图形渲染，与 AI 训练无关——常见干扰项。"},{"en":"HBM","zh":"高带宽显存","k":"gpu-hw","ce":"High Bandwidth Memory (HBM)","cz":"高带宽显存","eb":"Stacked memory inside the GPU package with very high bandwidth; used by data center GPUs (A100 HBM2e, H100 HBM3, H200/B200 HBM3e).","zb":"堆叠在 GPU 封装内的高带宽显存，数据中心 GPU 使用（A100 HBM2e、H100 HBM3、H200/B200 HBM3e）。"},{"en":"Memory bandwidth","zh":"显存带宽","k":"gpu-hw","ce":"Memory bandwidth","cz":"显存带宽","eb":"Data read/written from GPU memory per second (TB/s). The bottleneck for memory-bound work such as LLM decode.","zb":"每秒能从显存读写的数据量（TB/s）。访存密集型任务（如 LLM decode）的瓶颈。"},{"en":"Compute- vs memory-bound","zh":"计算密集 vs 访存密集","k":"gpu-hw","ce":"Compute-bound vs memory-bound","cz":"计算密集 vs 访存密集","eb":"Compute-bound: limited by FLOPS (large GEMMs). Memory-bound: limited by bandwidth (element-wise ops, LLM decode).","zb":"计算密集：受 FLOPS 限制（大矩阵乘）；访存密集：受带宽限制（逐元素运算、LLM decode）。"},{"en":"Warp (32 threads)","zh":"线程束（32 线程）","k":"gpu-hw","ce":"Warp","cz":"线程束","eb":"The basic GPU scheduling unit: 32 threads executing the same instruction together (SIMT).","zb":"GPU 调度的基本单位：32 个线程同时执行同一条指令（SIMT）。"},{"en":"Compute capability","zh":"计算能力版本","k":"gpu-hw","ce":"Compute capability","cz":"计算能力版本","eb":"GPU architecture feature version: A100 = 8.0, Ada = 8.9, H100 = 9.0, B200 = 10.0. Compile targets (sm_XX) must match.","zb":"GPU 架构特性版本号：A100 = 8.0，Ada = 8.9，H100 = 9.0，B200 = 10.0。编译时 sm_XX 要匹配。"}]},{"en":"GPU Generations","zh":"GPU 架构代际","c":[{"en":"Volta · V100","zh":"Volta · 首个 Tensor Core","k":"gpu-gen","ce":"Volta (V100, 2017)","cz":"","eb":"First-generation Tensor Cores; NVLink 2 (300 GB/s).","zb":"第一代 Tensor Core；NVLink 2（300 GB/s）。"},{"en":"Turing · T4","zh":"Turing · 推理卡 T4","k":"gpu-gen","ce":"Turing (T4, 2018)","cz":"","eb":"INT8/INT4 Tensor Cores and RT Cores. T4 is the classic 70 W low-power inference card (16 GB).","zb":"INT8/INT4 Tensor Core、RT Core。T4 是经典 70 W 低功耗推理卡（16 GB）。"},{"en":"Ampere · A100","zh":"Ampere · MIG / TF32","k":"gpu-gen","ce":"Ampere (A100, 2020)","cz":"","eb":"MIG (up to 7 instances), TF32, 2:4 structured sparsity, 3rd-gen Tensor Cores, NVLink 3 (600 GB/s).","zb":"MIG（最多 7 实例）、TF32、2:4 结构化稀疏、第三代 Tensor Core、NVLink 3（600 GB/s）。"},{"en":"Ada · L4 / L40S","zh":"Ada · 推理与图形","k":"gpu-gen","ce":"Ada Lovelace (L4 / L40S / RTX 40)","cz":"","eb":"4th-gen Tensor Cores with FP8; aimed at inference, graphics, and video. The RTX 4070 in this repo is Ada.","zb":"第四代 Tensor Core，支持 FP8；面向推理、图形、视频。本仓库的 RTX 4070 就是 Ada。"},{"en":"Hopper · H100","zh":"Hopper · FP8 Transformer Engine","k":"gpu-gen","ce":"Hopper (H100, 2022)","cz":"","eb":"Transformer Engine (FP8), 4th-gen Tensor Cores, NVLink 4 (900 GB/s), confidential computing, 2nd-gen MIG, DPX.","zb":"Transformer Engine（FP8）、第四代 Tensor Core、NVLink 4（900 GB/s）、机密计算、第二代 MIG、DPX。"},{"en":"H200","zh":"H200 · 141 GB HBM3e","k":"gpu-gen","ce":"H200","cz":"","eb":"Hopper with 141 GB HBM3e and ~4.8 TB/s. Mainly more memory and bandwidth than H100, which helps LLM inference.","zb":"Hopper 架构，141 GB HBM3e、~4.8 TB/s。相比 H100 主要提升显存容量和带宽，利好 LLM 推理。"},{"en":"GH200 Grace Hopper","zh":"GH200 · NVLink-C2C","k":"gpu-gen","ce":"GH200 Grace Hopper Superchip","cz":"","eb":"Grace CPU + H100/H200 GPU over coherent NVLink-C2C (900 GB/s); the GPU can access large CPU memory directly.","zb":"Grace CPU + H100/H200 GPU，通过 NVLink-C2C（900 GB/s）一致性互联，GPU 可直接访问大容量 CPU 内存。"},{"en":"Blackwell · B200","zh":"Blackwell · FP4 / NVLink 5","k":"gpu-gen","ce":"Blackwell (B200, 2024)","cz":"","eb":"2nd-gen Transformer Engine (FP4/FP6), NVLink 5 (1.8 TB/s), dual-die design, RAS engine, decompression engine.","zb":"第二代 Transformer Engine（FP4/FP6）、NVLink 5（1.8 TB/s）、双芯片设计、RAS 引擎、解压引擎。"},{"en":"GB200 NVL72","zh":"GB200 NVL72 机柜","k":"gpu-gen","ce":"GB200 NVL72","cz":"","eb":"Liquid-cooled rack: 36 Grace CPUs + 72 Blackwell GPUs in one NVLink domain, acting like one giant GPU for trillion-parameter LLMs.","zb":"液冷机柜：36 Grace + 72 Blackwell GPU，在同一个 NVLink 域内，像一块巨型 GPU，面向万亿参数 LLM。"},{"en":"\"First introduced in\"","zh":"“首次引入”速记","k":"gpu-gen","ce":"\"First introduced in\" cheat sheet","cz":"“首次引入”速记","eb":"NVLink = Pascal; Tensor Core = Volta; RT Core = Turing; MIG/TF32/sparsity = Ampere; FP8 Transformer Engine = Hopper; FP4/NVLink 5 = Blackwell.","zb":"NVLink=Pascal；Tensor Core=Volta；RT Core=Turing；MIG/TF32/稀疏=Ampere；FP8 Transformer Engine=Hopper；FP4/NVLink5=Blackwell。"}]},{"en":"Numeric Precision","zh":"数值精度","c":[{"en":"FP32","zh":"单精度","k":"precision","ce":"FP32","cz":"单精度浮点","eb":"Single precision: 8 exponent + 23 mantissa bits. Traditional training baseline; holds master weights in mixed precision.","zb":"单精度，8 位指数 + 23 位尾数。传统训练基线，混合精度中保存主权重。"},{"en":"TF32","zh":"TF32（Ampere）","k":"precision","ce":"TF32","cz":"","eb":"Ampere Tensor Core math mode: 8-bit exponent (FP32 range) + 10-bit mantissa. Speeds up FP32 code with no code changes.","zb":"Ampere 引入的 Tensor Core 计算模式：8 位指数（同 FP32 范围）+ 10 位尾数。FP32 代码无需修改即可加速。"},{"en":"BF16","zh":"BF16（同 FP32 范围）","k":"precision","ce":"BF16 (bfloat16)","cz":"","eb":"16 bits: 8 exponent + 7 mantissa bits. Same dynamic range as FP32, stable training, usually no loss scaling needed.","zb":"16 位：8 位指数 + 7 位尾数。与 FP32 动态范围相同，训练稳定，一般不需要 loss scaling。"},{"en":"FP16","zh":"半精度","k":"precision","ce":"FP16 (half precision)","cz":"半精度","eb":"16 bits: 5 exponent + 10 mantissa bits. More precision than BF16 but smaller range; training needs loss scaling to avoid underflow.","zb":"16 位：5 位指数 + 10 位尾数。精度比 BF16 高但范围小，训练需要 loss scaling 防下溢。"},{"en":"FP8 (E4M3 / E5M2)","zh":"FP8（Hopper）","k":"precision","ce":"FP8 (E4M3 / E5M2)","cz":"","eb":"Introduced with Hopper. E4M3 has more precision (often forward pass); E5M2 has more range (often gradients). Managed by the Transformer Engine.","zb":"Hopper 引入。E4M3 精度高（常用于前向），E5M2 范围大（常用于梯度）。由 Transformer Engine 管理。"},{"en":"FP4 / NVFP4","zh":"FP4（Blackwell）","k":"precision","ce":"FP4 / NVFP4","cz":"","eb":"4-bit floating point supported by Blackwell, mainly for inference, with block-level scale factors to preserve accuracy.","zb":"Blackwell 支持的 4 位浮点，主要用于推理，配合块级缩放因子保持精度。"},{"en":"INT8 / INT4","zh":"整数量化","k":"precision","ce":"INT8","cz":"","eb":"8-bit integer, common for inference quantization; requires calibration to set scale factors.","zb":"8 位整数，推理量化常用；需要校准（calibration）确定缩放因子。"},{"en":"Mixed precision","zh":"混合精度训练","k":"precision","ce":"Mixed precision training","cz":"混合精度训练","eb":"Matrix math in FP16/BF16 on Tensor Cores while keeping FP32 master weights: faster, less memory, accuracy essentially unchanged.","zb":"矩阵运算用 FP16/BF16（Tensor Core 加速），保留 FP32 主权重。更快、更省显存、精度基本不变。"},{"en":"Quantization","zh":"量化","k":"precision","ce":"Quantization","cz":"量化","eb":"Converting weights/activations from high to low precision (FP8/INT8/INT4/FP4): less memory, more throughput, possible small accuracy loss.","zb":"把权重/激活从高精度转为低精度（FP8/INT8/INT4/FP4）：显存↓、吞吐↑，可能有少量精度损失。"},{"en":"Bytes per parameter","zh":"每参数字节数","k":"precision","ce":"Bytes per parameter","cz":"每参数字节数","eb":"FP32 = 4, FP16/BF16 = 2, FP8/INT8 = 1, INT4/FP4 = 0.5.","zb":"FP32 = 4，FP16/BF16 = 2，FP8/INT8 = 1，INT4/FP4 = 0.5。"}]},{"en":"NVIDIA Software Stack","zh":"NVIDIA 软件栈","c":[{"en":"Stack layers","zh":"软件栈分层","k":"sw-stack","ce":"GPU software stack layers (bottom to top)","cz":"GPU 软件栈分层（自下而上）","eb":"GPU driver → CUDA (runtime + CUDA-X libraries) → frameworks (PyTorch/TF/JAX) → platforms and services (NGC, AI Enterprise, NIM) → applications.","zb":"GPU 驱动 → CUDA（运行时 + CUDA-X 库）→ 框架（PyTorch/TF/JAX）→ 平台与服务（NGC、AI Enterprise、NIM）→ 应用。"},{"en":"Libraries","zh":"加速库","c":[{"en":"CUDA","zh":"并行计算平台","k":"sw-stack","ce":"CUDA","cz":"","eb":"NVIDIA's parallel computing platform and programming model, including compiler, runtime, libraries, and tools.","zb":"NVIDIA 的并行计算平台与编程模型，包含编译器、运行时、库和工具。"},{"en":"CUDA Toolkit","zh":"CUDA 工具包","k":"sw-stack","ce":"CUDA Toolkit","cz":"CUDA 工具包","eb":"Developer kit: nvcc compiler, CUDA runtime, math libraries, cuda-gdb, Nsight tools. Not needed on the host to run containerized apps.","zb":"开发套件：nvcc 编译器、CUDA 运行时、数学库、cuda-gdb、Nsight 工具。运行容器化应用时宿主机不需要安装。"},{"en":"cuDNN","zh":"深度网络原语库","k":"sw-stack","ce":"cuDNN","cz":"","eb":"Library of deep neural network primitives: convolution, attention, normalization, activations. Called by frameworks under the hood.","zb":"深度神经网络原语库：卷积、注意力、归一化、激活等。框架底层调用。"},{"en":"cuBLAS","zh":"线性代数库","k":"sw-stack","ce":"cuBLAS","cz":"","eb":"GPU-accelerated basic linear algebra library (GEMM and more).","zb":"GPU 加速的基础线性代数库（矩阵乘 GEMM 等）。"},{"en":"NCCL","zh":"集合通信库","k":"sw-stack","ce":"NCCL","cz":"","eb":"NVIDIA Collective Communications Library (\"nickel\"): all-reduce, all-gather, broadcast across GPUs and nodes.","zb":"NVIDIA Collective Communications Library（读作 nickel）：all-reduce、all-gather、broadcast 等多 GPU/多节点集合通信。"},{"en":"Magnum IO","zh":"数据中心 IO 加速","k":"sw-stack","ce":"Magnum IO","cz":"","eb":"Umbrella name for data center I/O acceleration: GPUDirect RDMA/Storage, NCCL, NVSHMEM, UCX, in-network computing.","zb":"数据中心 IO 加速栈的统称：GPUDirect RDMA/Storage、NCCL、NVSHMEM、UCX、网络在网计算等。"}]},{"en":"Inference","zh":"推理","c":[{"en":"TensorRT","zh":"推理优化器","k":"sw-stack","ce":"TensorRT","cz":"","eb":"Inference optimizer + runtime: layer fusion, precision calibration (FP16/INT8/FP8), kernel auto-tuning; produces an optimized engine.","zb":"推理优化器 + 运行时：层融合、精度校准（FP16/INT8/FP8）、kernel 自动调优，生成优化后的 engine。"},{"en":"TensorRT-LLM","zh":"LLM 推理优化","k":"sw-stack","ce":"TensorRT-LLM","cz":"","eb":"Library optimized for LLM inference: in-flight batching, paged KV cache, quantization (FP8/INT4/FP4), tensor parallelism.","zb":"专为 LLM 推理优化的库：in-flight batching、paged KV cache、量化（FP8/INT4/FP4）、张量并行。"},{"en":"Triton Inference Server","zh":"Triton 推理服务器","k":"sw-stack","ce":"Triton Inference Server","cz":"Triton 推理服务器","eb":"Open-source serving software: multiple framework backends, dynamic batching, concurrent models, model repository, HTTP/gRPC, Prometheus metrics.","zb":"开源推理服务软件：多框架后端、动态批处理、多模型并发、模型仓库、HTTP/gRPC、Prometheus 指标。"},{"en":"Triton dynamic batching","zh":"Triton 动态批处理","k":"sw-stack","ce":"Triton dynamic batching","cz":"Triton 动态批处理","eb":"The server merges independent requests into one batch automatically to raise throughput.","zb":"服务端把多个独立请求自动合并成一个 batch 执行，提高吞吐。"},{"en":"NIM","zh":"推理微服务","k":"sw-stack","ce":"NVIDIA Inference Microservices (NIM)","cz":"NVIDIA 推理微服务","eb":"Prepackaged, pre-optimized inference containers exposing standard (OpenAI-compatible) APIs; deploy quickly on any NVIDIA GPU environment.","zb":"预打包、预优化的推理微服务容器，提供标准（OpenAI 兼容）API，可在任何 NVIDIA GPU 环境快速部署。"},{"en":"Dynamo","zh":"分布式 LLM 推理框架","k":"sw-stack","ce":"NVIDIA Dynamo","cz":"","eb":"Open-source framework for large-scale distributed LLM serving, with prefill/decode disaggregation and KV-cache-aware routing.","zb":"面向大规模分布式 LLM 推理的开源服务框架，支持 prefill/decode 分离、KV cache 感知路由。"}]},{"en":"Platforms & Frameworks","zh":"平台与框架","c":[{"en":"NGC Catalog","zh":"NGC 目录","k":"sw-stack","ce":"NGC Catalog","cz":"NGC 目录","eb":"NVIDIA's hub for GPU-optimized software: framework containers (monthly), pretrained models, Helm charts, SDKs.","zb":"NVIDIA GPU 优化软件中心：框架容器（每月更新）、预训练模型、Helm chart、SDK。"},{"en":"NVIDIA AI Enterprise","zh":"企业级 AI 软件套件","k":"sw-stack","ce":"NVIDIA AI Enterprise","cz":"","eb":"Enterprise AI software suite including NIM, NeMo, Triton, RAPIDS, with enterprise support, security patches, and stable branches; licensed per GPU.","zb":"企业级 AI 软件套件：包含 NIM、NeMo、Triton、RAPIDS 等，提供企业支持、安全补丁、稳定分支；按 GPU 授权。"},{"en":"NeMo","zh":"生成式 AI 框架","k":"sw-stack","ce":"NeMo","cz":"","eb":"Framework to build, customize, and deploy generative AI: data curation, training, fine-tuning, evaluation, guardrails.","zb":"构建、定制、部署生成式 AI 的框架：数据整理、训练、微调、评估、护栏。"},{"en":"RAPIDS","zh":"GPU 数据科学","k":"sw-stack","ce":"RAPIDS","cz":"","eb":"GPU-accelerated data science suite: cuDF (pandas-like), cuML (scikit-learn-like), cuGraph (graph analytics), cuVS (vector search).","zb":"GPU 加速数据科学套件：cuDF（类 pandas）、cuML（类 scikit-learn）、cuGraph（图分析）、cuVS（向量搜索）。"},{"en":"DALI","zh":"GPU 数据加载","k":"sw-stack","ce":"DALI","cz":"","eb":"Data Loading Library: decodes and augments data on the GPU to remove the CPU preprocessing bottleneck.","zb":"Data Loading Library：在 GPU 上做数据解码与增强，解决 CPU 预处理瓶颈。"},{"en":"Nsight Systems","zh":"系统级性能分析","k":"sw-stack","ce":"Nsight Systems","cz":"","eb":"System-wide profiler: CPU/GPU timeline to find I/O, synchronization, and gaps between kernels.","zb":"系统级性能分析：CPU/GPU 时间线，找出 IO、同步、kernel 间空隙等瓶颈。"}]}]},{"en":"Distributed Training","zh":"分布式训练","c":[{"en":"Data parallelism","zh":"数据并行","k":"parallel","ce":"Data parallelism","cz":"数据并行","eb":"Each GPU holds a full model copy and gets a slice of the mini-batch; gradients are averaged with all-reduce after backward. The most common approach.","zb":"每张 GPU 一份完整模型，切分 mini-batch；反向后 all-reduce 平均梯度。最常用的并行方式。"},{"en":"Tensor parallelism","zh":"张量并行","k":"parallel","ce":"Tensor parallelism","cz":"张量并行","eb":"Splits matrices within a layer across GPUs; communicates every layer, so it is usually kept inside a node's NVLink domain.","zb":"把单层内的矩阵切分到多 GPU，每层都要通信，通信极频繁 → 一般限制在节点内 NVLink 域。"},{"en":"Pipeline parallelism","zh":"流水线并行","k":"parallel","ce":"Pipeline parallelism","cz":"流水线并行","eb":"Splits layers into stages on different GPUs and uses micro-batches to fill the pipeline and reduce bubbles.","zb":"按层把模型分成多个 stage 放在不同 GPU，用 micro-batch 填充流水线减少气泡。"},{"en":"ZeRO / FSDP","zh":"分片数据并行","k":"parallel","ce":"Fully Sharded Data Parallel (FSDP)","cz":"全分片数据并行","eb":"PyTorch's fully sharded data parallelism; same idea as ZeRO-3.","zb":"PyTorch 的全分片数据并行，思路同 ZeRO-3。"},{"en":"All-reduce","zh":"全归约","k":"parallel","ce":"All-reduce","cz":"全归约","eb":"Sums (or averages) data from all GPUs and gives every GPU the full result. Used to sync gradients in data parallelism.","zb":"所有 GPU 的数据求和（或平均）后，每个 GPU 都得到完整结果。数据并行同步梯度用。"},{"en":"Ring vs tree all-reduce","zh":"环形 vs 树形","k":"parallel","ce":"Tree all-reduce","cz":"树形全归约","eb":"Tree-shaped reduction; latency grows logarithmically, good for large scale and small messages. NCCL picks ring or tree automatically.","zb":"树形归约，延迟随 GPU 数对数增长，适合大规模、小消息。NCCL 会自动选 ring 或 tree。"},{"en":"nccl-tests busbw","zh":"nccl-tests 总线带宽","k":"parallel","ce":"algbw vs busbw","cz":"算法带宽 vs 总线带宽","eb":"algbw = data size ÷ time; busbw corrects for the algorithm to reflect actual link bandwidth, comparable to NVLink/NIC specs.","zb":"algbw = 数据量 ÷ 时间；busbw 按算法修正后反映硬件链路实际带宽，可与 NVLink/网卡理论值对比。"},{"en":"Scaling efficiency","zh":"扩展效率","k":"parallel","ce":"Scaling efficiency","cz":"扩展效率","eb":"Actual speedup on N GPUs ÷ N. Drops due to communication overhead, insufficient network bandwidth, I/O, or load imbalance.","zb":"N 张 GPU 的实际加速比 ÷ N。下降常因通信开销、网络带宽不足、IO 或负载不均。"},{"en":"Training memory ≈ 16 B/param","zh":"训练显存估算","k":"parallel","ce":"Training memory estimate (Adam, mixed precision)","cz":"训练显存估算（Adam 混合精度）","eb":"~16 bytes/parameter (FP16 weights 2 + grads 2 + FP32 master 4 + two Adam states 8), excluding activations. 7B model ≈ 112 GB.","zb":"约 16 字节/参数（FP16 权重 2 + 梯度 2 + FP32 主权重 4 + Adam 两份状态 8），还不含激活。7B 模型约 112 GB。"},{"en":"Inference memory","zh":"推理显存估算","k":"parallel","ce":"Inference memory estimate","cz":"推理显存估算","eb":"Weights = parameters × bytes per parameter (70B × 2 B = 140 GB), plus KV cache and activations.","zb":"权重 = 参数量 × 每参数字节（70B × 2 B = 140 GB），再加 KV cache 和激活。"}]},{"en":"Generative AI & LLM","zh":"生成式 AI 与 LLM","c":[{"en":"Token","zh":"词元","k":"genai","ce":"Token","cz":"词元","eb":"The basic unit of text a model processes (word or subword). In English, 1 token ≈ 0.75 words. Billing and performance are measured in tokens.","zb":"模型处理文本的基本单位（词或子词）。英文约 1 token ≈ 0.75 个单词。计费和性能都按 token 计。"},{"en":"RAG","zh":"检索增强生成","k":"genai","ce":"Retrieval-augmented generation (RAG)","cz":"检索增强生成","eb":"Chunk docs → embed → store in a vector DB; at query time retrieve relevant chunks into the prompt. First choice when data changes often and you don't want to retrain.","zb":"文档切块 → embedding → 存入向量库；提问时检索相关片段拼入 prompt 再生成。数据经常变、不想重训时首选。"},{"en":"Vector database","zh":"向量数据库","k":"genai","ce":"Vector database","cz":"向量数据库","eb":"Stores embeddings and retrieves by vector similarity (e.g., Milvus). GPU acceleration via cuVS.","zb":"存储 embedding，按向量相似度检索（如 Milvus）。GPU 加速可用 cuVS。"},{"en":"LoRA / PEFT","zh":"参数高效微调","k":"genai","ce":"LoRA","cz":"低秩适配","eb":"Low-Rank Adaptation: freezes the original weights and trains small low-rank matrices added to layers. Far cheaper than full fine-tuning.","zb":"Low-Rank Adaptation：冻结原权重，训练小的低秩矩阵加到原层上。显存和成本远低于全量微调。"},{"en":"RAG vs fine-tuning","zh":"RAG 与微调怎么选","k":"genai","ce":"RAG vs fine-tuning: how to choose","cz":"RAG 与微调怎么选","eb":"Frequently changing knowledge or need for citations → RAG; changing style/format/specific skills → fine-tuning; they can be combined.","zb":"知识频繁变化、需要引用来源 → RAG；改变风格/格式/特定能力 → 微调；二者可结合。"},{"en":"Mixture of Experts","zh":"混合专家","k":"genai","ce":"Mixture of Experts (MoE)","cz":"混合专家模型","eb":"Each layer has many expert subnetworks and each token activates only a few: huge total parameters, small per-token compute.","zb":"每层有多个专家子网络，每个 token 只激活其中少数，总参数大而单 token 计算量小。"},{"en":"Prefill vs decode","zh":"预填充 vs 解码","k":"genai","ce":"Prefill vs decode","cz":"预填充 vs 解码","eb":"Prefill processes the whole prompt at once (compute-bound); decode generates tokens one by one (memory-bandwidth-bound).","zb":"Prefill：一次性处理整个输入 prompt，计算密集；Decode：逐个生成 token，受显存带宽限制。"},{"en":"KV cache","zh":"键值缓存","k":"genai","ce":"KV cache","cz":"键值缓存","eb":"Caches attention keys/values already computed to avoid recomputation; grows linearly with context length and concurrency and uses lots of memory.","zb":"缓存注意力层已算过的 Key/Value，避免重复计算；随上下文长度和并发数线性增长，吃大量显存。"},{"en":"In-flight batching","zh":"连续批处理","k":"genai","ce":"In-flight / continuous batching","cz":"飞行中批处理 / 连续批处理","eb":"Requests join the batch as they arrive and leave when done instead of waiting for the whole batch, greatly raising LLM serving throughput.","zb":"请求随到随加入、完成即退出 batch，而不是等整批结束，大幅提高 LLM 服务吞吐。"},{"en":"TTFT","zh":"首 token 延迟","k":"genai","ce":"Time to first token (TTFT)","cz":"首 token 延迟","eb":"Time from sending a request to receiving the first token; driven mainly by prefill and queuing.","zb":"从发送请求到收到第一个 token 的时间，主要受 prefill 和排队影响。"},{"en":"TPOT / ITL","zh":"每 token 时间","k":"genai","ce":"TPOT / ITL","cz":"每 token 输出时间 / token 间延迟","eb":"Time Per Output Token / Inter-Token Latency: the gap between later tokens, i.e., the \"typing speed\".","zb":"Time Per Output Token / Inter-Token Latency：后续每个 token 的间隔，决定“打字速度”。"},{"en":"Hallucination","zh":"幻觉","k":"genai","ce":"Hallucination","cz":"幻觉","eb":"The model produces plausible but false content. Mitigate with RAG, guardrails, fact checking.","zb":"模型生成看似合理但不真实的内容。缓解：RAG、护栏、事实校验。"}]},{"en":"Industry & Edge","zh":"行业方案与边缘","c":[{"en":"Omniverse","zh":"数字孪生","k":"industry","ce":"Omniverse","cz":"","eb":"Platform for 3D collaboration, simulation, and digital twins, built on OpenUSD.","zb":"3D 协作、仿真与数字孪生平台，基于 OpenUSD。"},{"en":"Metropolis","zh":"视觉 AI","k":"industry","ce":"Metropolis","cz":"","eb":"Vision AI / intelligent video analytics platform (smart cities, retail, factories).","zb":"智能视频分析 / 视觉 AI 平台（智慧城市、零售、工厂）。"},{"en":"Clara","zh":"医疗健康","k":"industry","ce":"Clara","cz":"","eb":"Healthcare AI platform: medical imaging, genomics (Parabricks), drug discovery (BioNeMo).","zb":"医疗健康 AI 平台：医学影像、基因组学（Parabricks）、药物研发（BioNeMo）。"},{"en":"Riva","zh":"语音 AI","k":"industry","ce":"Riva","cz":"","eb":"Speech AI SDK: automatic speech recognition (ASR), text-to-speech (TTS), translation.","zb":"语音 AI SDK：语音识别（ASR）、语音合成（TTS）、翻译。"},{"en":"Jetson","zh":"嵌入式边缘","k":"gpu-gen","ce":"Jetson (Orin / Thor)","cz":"","eb":"Embedded edge AI modules for robots, drones, and smart cameras.","zb":"嵌入式边缘 AI 模组，用于机器人、无人机、智能摄像头。"},{"en":"Fleet Command","zh":"边缘远程管理","k":"industry","ce":"Fleet Command","cz":"","eb":"Cloud service for remotely deploying and managing edge AI (zero-touch provisioning, OTA updates, security).","zb":"边缘 AI 远程部署和管理的云服务（零接触配置、OTA 更新、安全）。"},{"en":"AI factory","zh":"AI 工厂","k":"industry","ce":"AI factory","cz":"AI 工厂","eb":"NVIDIA's framing of the data center as a factory that produces intelligence (tokens), measured by token throughput and energy efficiency.","zb":"NVIDIA 提出的概念：把数据中心看作生产“智能”（token）的工厂，以 token 吞吐和能效衡量。"}]}],"d":1,"w":"38%"},{"en":"AI Infrastructure","zh":"AI 基础设施","c":[{"en":"Compute Nodes","zh":"计算节点","c":[{"en":"PCIe vs SXM","zh":"PCIe 卡 vs SXM 模组","k":"compute","ce":"PCIe card vs SXM module","cz":"PCIe 卡 vs SXM 模组","eb":"PCIe: fits standard slots, lower power, GPUs talk over PCIe or an NVLink bridge. SXM: mounted on an HGX baseboard, all-to-all NVSwitch, higher power and performance.","zb":"PCIe：插标准槽，功耗低，GPU 间走 PCIe 或 NVLink bridge。SXM：装在 HGX 基板上，NVSwitch 全互联，功耗和性能更高。"},{"en":"HGX vs DGX","zh":"HGX 与 DGX","k":"compute","ce":"HGX vs DGX in one sentence","cz":"一句话区分 HGX 与 DGX","eb":"HGX is the GPU board platform for OEMs; DGX is the complete system NVIDIA sells.","zb":"HGX 是给 OEM 的 GPU 主板平台；DGX 是 NVIDIA 卖的整机。"},{"en":"DGX H100","zh":"8× H100 · 640 GB · ~10.2 kW","k":"compute","ce":"DGX H100 configuration","cz":"DGX H100 配置","eb":"8× H100 SXM (640 GB HBM3 total), 4 NVSwitch chips, 8× 400 Gb/s ConnectX-7 compute ports, 2 Intel Xeon CPUs, 2 TB RAM, ~10.2 kW max.","zb":"8× H100 SXM（共 640 GB HBM3）、4 颗 NVSwitch 芯片、8 个 400 Gb/s ConnectX-7 计算端口、2 颗 Intel Xeon、2 TB 内存，最大约 10.2 kW。"},{"en":"DGX B200","zh":"8× B200 · 1,440 GB","k":"compute","ce":"DGX B200 configuration","cz":"DGX B200 配置","eb":"8× B200 (1,440 GB HBM3e total), NVLink 5, ~14 kW-class max power.","zb":"8× B200（共 1,440 GB HBM3e），NVLink 5，最大约 14 kW 级。"},{"en":"GB200 NVL72","zh":"72 GPU 一个 NVLink 域","k":"compute","ce":"What does \"72\" in NVL72 mean?","cz":"NVL72 中的 “72”","eb":"The number of Blackwell GPUs in one NVLink domain.","zb":"一个 NVLink 域里的 Blackwell GPU 数量。"},{"en":"NVIDIA-Certified Systems","zh":"NVIDIA 认证系统","k":"compute","ce":"NVIDIA-Certified Systems","cz":"NVIDIA 认证系统","eb":"OEM servers tested and validated by NVIDIA (performance, manageability, security, networking, scalability); eligible for NVIDIA AI Enterprise support.","zb":"OEM 服务器经 NVIDIA 测试验证（性能、管理、安全、网络、可扩展性），可获 NVIDIA AI Enterprise 支持。"},{"en":"BMC","zh":"基板管理控制器","k":"compute","ce":"Baseboard Management Controller (BMC)","cz":"基板管理控制器","eb":"Independent management chip on the motherboard; via the out-of-band network it provides remote power, sensors, logs, remote console (IPMI/Redfish).","zb":"服务器主板上的独立管理芯片，经带外网络提供远程电源控制、传感器、日志、远程控制台（IPMI/Redfish）。"},{"en":"Grace + GPU benefit","zh":"Grace 超级芯片的好处","k":"compute","ce":"Benefit of Grace Hopper / Grace Blackwell","cz":"Grace Hopper / Grace Blackwell 的好处","eb":"CPU and GPU share coherent NVLink-C2C (900 GB/s), so the GPU can access large CPU memory fast, avoiding the PCIe bottleneck.","zb":"CPU 和 GPU 通过 NVLink-C2C 一致性互联（900 GB/s），GPU 可高速访问大容量 CPU 内存，减少 PCIe 瓶颈。"}]},{"en":"Intra-node Interconnect","zh":"节点内互联","c":[{"en":"PCIe bandwidth","zh":"PCIe 带宽","k":"interconnect","ce":"PCIe x16 one-way bandwidth per generation","cz":"PCIe 每代 x16 单向带宽","eb":"Gen3 ≈ 16 GB/s, Gen4 ≈ 32 GB/s, Gen5 ≈ 64 GB/s, Gen6 ≈ 128 GB/s. Double for bidirectional.","zb":"Gen3 ≈ 16 GB/s，Gen4 ≈ 32 GB/s，Gen5 ≈ 64 GB/s，Gen6 ≈ 128 GB/s。双向翻倍。"},{"en":"NVLink","zh":"GPU 直连","k":"interconnect","ce":"NVLink","cz":"","eb":"High-bandwidth, low-latency point-to-point interconnect between GPUs (and GPU–CPU), far faster than PCIe.","zb":"GPU 之间（及 GPU-CPU）的高带宽、低延迟点对点互联，带宽远高于 PCIe。"},{"en":"NVLink per generation","zh":"NVLink 代际带宽","k":"interconnect","ce":"NVLink bandwidth per GPU by generation","cz":"NVLink 每代每 GPU 带宽","eb":"NVLink 1 (P100) 160 GB/s → 2 (V100) 300 → 3 (A100) 600 → 4 (H100) 900 GB/s → 5 (B200) 1.8 TB/s.","zb":"NVLink 1（P100）160 GB/s → 2（V100）300 → 3（A100）600 → 4（H100）900 GB/s → 5（B200）1.8 TB/s。"},{"en":"NVSwitch","zh":"NVLink 交换芯片","k":"interconnect","ce":"NVSwitch","cz":"","eb":"NVLink switch chip that lets every GPU in a node talk to every other at full NVLink bandwidth, with no multi-hop.","zb":"NVLink 交换芯片：让节点内所有 GPU 两两以全 NVLink 带宽通信，不需要多跳。"},{"en":"NVLink-C2C","zh":"芯片间一致性互联","k":"interconnect","ce":"NVLink-C2C","cz":"","eb":"Coherent chip-to-chip interconnect (Grace↔Hopper, Grace↔Blackwell), 900 GB/s.","zb":"芯片到芯片的一致性互联（Grace↔Hopper、Grace↔Blackwell），900 GB/s。"},{"en":"Fabric Manager","zh":"NVSwitch 必需服务","k":"interconnect","ce":"Fabric Manager","cz":"","eb":"Service required on NVSwitch systems (HGX A100/H100, etc.) to configure NVSwitches and NVLink partitions; if not running, CUDA initialization fails.","zb":"NVSwitch 系统（HGX A100/H100 等）上必须运行的服务，负责配置 NVSwitch 和 NVLink 分区；没运行会导致 CUDA 初始化失败。"},{"en":"topo -m: NV# > … > SYS","zh":"拓扑矩阵快慢顺序","k":"interconnect","ce":"topo matrix from fastest to slowest","cz":"拓扑矩阵从快到慢","eb":"NV# > PIX > PXB > PHB > NODE > SYS.","zb":"NV# > PIX > PXB > PHB > NODE > SYS。"},{"en":"NUMA & CPU affinity","zh":"NUMA 与 CPU 亲和性","k":"interconnect","ce":"Why CPU affinity matters","cz":"CPU 亲和性为什么重要","eb":"Binding processes to CPU cores on the same NUMA node as their GPU/NIC avoids cross-socket traffic that cuts bandwidth and adds latency.","zb":"进程绑定到与 GPU/网卡同一 NUMA 节点的 CPU 核，避免跨插槽访问降低带宽、增加延迟。"}]},{"en":"InfiniBand & RDMA","zh":"InfiniBand 与 RDMA","c":[{"en":"RDMA","zh":"远程直接内存访问","k":"network-ib","ce":"Remote Direct Memory Access (RDMA)","cz":"远程直接内存访问","eb":"The NIC reads/writes remote host memory directly without the remote CPU or kernel stack: low latency, high bandwidth, low CPU use.","zb":"网卡直接读写远端主机内存，不经过对方 CPU 和内核协议栈：低延迟、高带宽、低 CPU 占用。"},{"en":"InfiniBand","zh":"InfiniBand","k":"network-ib","ce":"InfiniBand (IB)","cz":"","eb":"Network designed for HPC/AI: native RDMA, credit-based lossless flow control, low latency, in-network computing (SHARP).","zb":"为 HPC/AI 设计的网络：原生 RDMA、基于信用的无损流控、低延迟、在网计算（SHARP）。"},{"en":"HDR 200 / NDR 400 / XDR 800","zh":"IB 速率","k":"network-ib","ce":"HDR / NDR / XDR","cz":"","eb":"HDR = 200 Gb/s, NDR = 400 Gb/s, XDR = 800 Gb/s per port.","zb":"HDR = 200 Gb/s，NDR = 400 Gb/s，XDR = 800 Gb/s（每端口）。"},{"en":"Credit-based flow control","zh":"基于信用的无损流控","k":"network-ib","ce":"Credit-based flow control","cz":"基于信用的流控","eb":"IB link-layer flow control: the sender transmits only when the receiver grants buffer credits, so congestion never drops packets (lossless).","zb":"IB 链路层流控：发送方只有在接收方给出缓冲“信用”时才发送，因此不会因拥塞丢包（无损）。"},{"en":"Subnet Manager","zh":"子网管理器","k":"network-ib","ce":"Subnet Manager (SM)","cz":"子网管理器","eb":"Required IB management entity: discovers topology, assigns LIDs, computes routing tables. Implemented by OpenSM or UFM's built-in SM.","zb":"IB 网络必需的管理实体：发现拓扑、分配 LID、计算路由表。实现：OpenSM 或 UFM 内置 SM。"},{"en":"SHARP","zh":"交换机内归约","k":"network-ib","ce":"SHARP","cz":"","eb":"Scalable Hierarchical Aggregation and Reduction Protocol: performs all-reduce and other reductions inside IB switches, cutting data movement and latency.","zb":"Scalable Hierarchical Aggregation and Reduction Protocol：在 IB 交换机内完成 all-reduce 等归约，减少数据往返、降低延迟。"},{"en":"UFM","zh":"IB 网络管理","k":"network-ib","ce":"Unified Fabric Manager (UFM)","cz":"统一网络管理器","eb":"InfiniBand fabric management platform: topology view, telemetry, alerts, health checks, built-in Subnet Manager.","zb":"InfiniBand 网络管理平台：拓扑可视化、遥测、告警、健康检查，内置 Subnet Manager。"},{"en":"ConnectX NICs","zh":"ConnectX 网卡","k":"network-ib","ce":"ConnectX","cz":"","eb":"NVIDIA (formerly Mellanox) NIC family supporting both IB and Ethernet. ConnectX-6 = 200G, ConnectX-7 = 400G, ConnectX-8 = 800G.","zb":"NVIDIA（原 Mellanox）的网卡系列，同时支持 IB 和以太网。ConnectX-6 = 200G，ConnectX-7 = 400G，ConnectX-8 = 800G。"},{"en":"Quantum switches","zh":"Quantum 交换机","k":"network-ib","ce":"Quantum switch family","cz":"Quantum 交换机系列","eb":"NVIDIA InfiniBand switches: Quantum (HDR), Quantum-2 (NDR, 64× 400G ports), Quantum-X800 (XDR).","zb":"NVIDIA InfiniBand 交换机：Quantum（HDR）、Quantum-2（NDR，64 个 400G 端口）、Quantum-X800（XDR）。"},{"en":"Partition / PKey","zh":"分区隔离","k":"network-ib","ce":"Partition / PKey","cz":"分区 / 分区键","eb":"IB isolation mechanism (like a VLAN): only ports in the same partition can talk; used for multi-tenancy.","zb":"IB 的网络隔离机制（类似 VLAN），只有同一分区的端口能互相通信，用于多租户。"}]},{"en":"Ethernet & Topology","zh":"以太网与拓扑","c":[{"en":"RoCE v2","zh":"以太网上的 RDMA","k":"network-eth","ce":"RoCE v1 vs RoCE v2","cz":"","eb":"v1: Layer 2 Ethernet, not routable. v2: encapsulated in UDP/IP (UDP 4791), routable across Layer 3; the mainstream choice.","zb":"v1：二层以太网，不可路由；v2：封装在 UDP/IP 中（UDP 4791），可跨三层路由，是主流。"},{"en":"PFC + ECN","zh":"无损以太网","k":"network-eth","ce":"Network requirements for RoCE","cz":"RoCE 对网络的要求","eb":"Needs a near-lossless fabric with congestion control such as PFC + ECN; packet loss sharply degrades performance.","zb":"需要接近无损：PFC + ECN 等拥塞控制；丢包会导致性能急剧下降。"},{"en":"IB vs Ethernet","zh":"IB 与以太网怎么选","k":"network-eth","ce":"InfiniBand vs Ethernet (RoCE): choosing","cz":"InfiniBand 与以太网（RoCE）怎么选","eb":"IB: native lossless, low latency, SHARP; the AI training benchmark. Ethernet: familiar operations, merges with existing networks, needs congestion-control tuning.","zb":"IB：原生无损、低延迟、SHARP，AI 训练性能标杆。以太网：运维生态熟悉、可与现有网络融合，需调优拥塞控制。"},{"en":"Spectrum-X","zh":"AI 以太网平台","k":"network-eth","ce":"Spectrum-X","cz":"","eb":"NVIDIA's AI Ethernet platform: Spectrum-4 switches + BlueField-3 SuperNICs with adaptive routing, congestion control, performance isolation.","zb":"NVIDIA 面向 AI 的以太网平台：Spectrum-4 交换机 + BlueField-3 SuperNIC，自适应路由、拥塞控制、性能隔离。"},{"en":"Fat-tree / leaf-spine","zh":"胖树 / 叶脊","k":"network-eth","ce":"Fat-tree","cz":"胖树","eb":"Multi-tier leaf-spine network that gets \"fatter\" toward the top, achieving non-blocking full bisection bandwidth; standard AI compute fabric topology.","zb":"叶-脊多层网络，越往上带宽越“胖”，可实现无阻塞全对分带宽，AI 计算网络的标准拓扑。"},{"en":"Non-blocking 1:1","zh":"无阻塞","k":"network-eth","ce":"Non-blocking","cz":"无阻塞","eb":"Uplink bandwidth equals downlink bandwidth (1:1, no oversubscription), so any server pairs can talk at full speed simultaneously.","zb":"上行带宽 = 下行带宽（1:1 无收敛），任意服务器对可同时满速通信。"},{"en":"Rail-optimized","zh":"轨道优化","k":"network-eth","ce":"Rail-optimized topology","cz":"轨道优化拓扑","eb":"GPU N's NIC in every server connects to the same leaf switch (rail N); same-index GPUs are one hop apart, matching NCCL traffic.","zb":"所有服务器的第 N 号 GPU 网卡连到同一台“第 N 号”叶交换机；同号 GPU 一跳可达，与 NCCL 通信模式匹配。"},{"en":"Four networks","zh":"四张网络","c":[{"en":"Compute fabric","zh":"计算网络","k":"network-eth","ce":"Compute fabric","cz":"计算网络","eb":"East-west network for cross-node GPU↔GPU traffic (IB or Spectrum-X), carrying distributed training traffic.","zb":"GPU↔GPU 跨节点东西向通信网络，IB 或 Spectrum-X，承载分布式训练流量。"},{"en":"Storage fabric","zh":"存储网络","k":"network-eth","ce":"Storage fabric","cz":"存储网络","eb":"Network for reaching high-performance shared storage, kept separate from the compute fabric so I/O doesn't disturb collectives.","zb":"节点访问高性能共享存储的网络，与计算网络隔离，避免 IO 干扰集合通信。"},{"en":"In-band management","zh":"带内管理","k":"network-eth","ce":"In-band management network","cz":"带内管理网络","eb":"SSH, cluster management, job scheduling, image and package downloads; goes through the OS.","zb":"SSH、集群管理、作业调度、镜像和软件包下载，走操作系统。"},{"en":"Out-of-band (BMC)","zh":"带外管理","k":"network-eth","ce":"Out-of-band (OOB) management network","cz":"带外管理网络","eb":"Connects BMCs (IPMI/Redfish) and switch management ports; works even when the OS is down for remote power cycling and logs.","zb":"连接 BMC（IPMI/Redfish）和交换机管理口；操作系统宕机也能远程开关机、看日志。"}]},{"en":"East-west vs north-south","zh":"东西向 vs 南北向","k":"network-eth","ce":"East-west vs north-south traffic","cz":"东西向 vs 南北向流量","eb":"East-west: between servers inside the data center (GPU↔GPU, to storage). North-south: in and out of the data center (user requests, internet).","zb":"东西向：数据中心内服务器之间（GPU↔GPU、到存储）；南北向：进出数据中心（用户请求、互联网）。"}]},{"en":"GPUDirect","zh":"GPUDirect","c":[{"en":"GPUDirect family","zh":"GPUDirect 家族","k":"gpudirect","ce":"The GPUDirect family","cz":"GPUDirect 家族","eb":"GPUDirect P2P (GPU↔GPU in a node), GPUDirect RDMA (NIC↔GPU memory), GPUDirect Storage (storage↔GPU memory).","zb":"GPUDirect P2P（节点内 GPU↔GPU）、GPUDirect RDMA（网卡↔GPU 显存）、GPUDirect Storage（存储↔GPU 显存）。"},{"en":"GPUDirect P2P","zh":"节点内 GPU 直连","k":"interconnect","ce":"GPUDirect P2P","cz":"GPUDirect 点对点","eb":"GPUs in the same node access each other's memory directly (over NVLink or PCIe) without going through CPU memory.","zb":"同一节点内 GPU 之间直接访问对方显存（经 NVLink 或 PCIe），不经过 CPU 内存。"},{"en":"GPUDirect RDMA","zh":"网卡 ↔ GPU 显存","k":"gpudirect","ce":"GPUDirect RDMA","cz":"","eb":"The NIC reads/writes GPU memory directly, eliminating staging copies through CPU memory; lowers cross-node latency and CPU load.","zb":"网卡直接读写 GPU 显存，省掉经过 CPU 内存的中转拷贝，降低跨节点通信延迟和 CPU 负载。"},{"en":"GPUDirect Storage","zh":"存储 ↔ GPU 显存","k":"gpudirect","ce":"GPUDirect Storage (GDS)","cz":"","eb":"Local NVMe, NVMe-oF, or parallel file systems DMA directly to/from GPU memory, bypassing the bounce buffer in CPU memory.","zb":"本地 NVMe、NVMe-oF 或并行文件系统通过 DMA 直接读写 GPU 显存，绕过 CPU 内存中的 bounce buffer。"},{"en":"Bounce buffer","zh":"中转缓冲区","k":"gpudirect","ce":"Bounce buffer","cz":"中转缓冲区","eb":"A staging buffer in CPU memory used when moving data between devices; GDS eliminates it.","zb":"数据在设备之间搬运时，先暂存到 CPU 内存的中转缓冲区。GDS 就是消除它。"},{"en":"Topology requirement","zh":"拓扑要求（PIX）","k":"gpudirect","ce":"Topology requirement for GPUDirect RDMA","cz":"GPUDirect RDMA 的拓扑要求","eb":"GPU and NIC should sit under the same PCIe switch (PIX); crossing CPU sockets (SYS) severely hurts performance.","zb":"GPU 与网卡最好在同一 PCIe 交换芯片下（PIX）；跨 CPU 插槽（SYS）性能会大幅下降。"}]},{"en":"DPU (BlueField)","zh":"DPU（BlueField）","c":[{"en":"DPU","zh":"数据处理器","k":"dpu","ce":"Data Processing Unit (DPU)","cz":"数据处理器","eb":"An \"infrastructure processor\" combining a fast NIC, Arm CPU cores, and acceleration engines to handle networking, storage, and security.","zb":"集成高速网卡、Arm CPU 核和加速引擎的“基础设施处理器”，处理网络、存储、安全任务。"},{"en":"CPU / GPU / DPU roles","zh":"三种处理器分工","k":"dpu","ce":"CPU / GPU / DPU roles","cz":"CPU / GPU / DPU 分工","eb":"CPU: general compute and control; GPU: accelerated compute; DPU: data center infrastructure (data movement, networking, storage, security).","zb":"CPU：通用计算与控制；GPU：加速计算；DPU：数据中心基础设施（数据搬运、网络、存储、安全）。"},{"en":"Offload & isolate","zh":"卸载与隔离","k":"dpu","ce":"Core value of a DPU","cz":"DPU 的核心价值","eb":"Offloads and accelerates infrastructure tasks from the host CPU and isolates them from tenant workloads (zero trust).","zb":"把基础设施任务从主机 CPU 卸载（offload）、加速，并与租户工作负载隔离（零信任）。"},{"en":"DOCA SDK","zh":"BlueField SDK","k":"dpu","ce":"DOCA","cz":"","eb":"Software framework/SDK for BlueField DPUs (libraries, drivers, services); plays the role CUDA plays for GPUs.","zb":"BlueField DPU 的软件框架/SDK：库、驱动、服务，地位类似 CUDA 之于 GPU。"},{"en":"Zero trust","zh":"零信任","k":"dpu","ce":"Why DPU isolation matters (zero trust)","cz":"DPU 隔离的意义（零信任）","eb":"The infrastructure control plane runs on the DPU, so even if the host is compromised, tenants cannot tamper with network/storage policy.","zb":"基础设施控制面运行在 DPU 上，即使主机被攻破，租户也无法篡改网络/存储策略。"},{"en":"Misconceptions","zh":"常见误区","k":"dpu","ce":"Common DPU misconceptions","cz":"DPU 常见误区","eb":"A DPU does not add GPU memory, does not replace NVSwitch, and does not train models.","zb":"DPU 不增加 GPU 显存、不替代 NVSwitch、不用来训练模型。"}]},{"en":"Storage","zh":"存储","c":[{"en":"Storage tiers","zh":"存储分层","k":"storage","ce":"Storage tiers","cz":"存储分层","eb":"GPU memory → system memory → local NVMe → high-performance shared storage/parallel FS → object storage/archive.","zb":"GPU 显存 → 系统内存 → 本地 NVMe → 高性能共享存储/并行文件系统 → 对象存储/归档。"},{"en":"Local NVMe","zh":"本地 NVMe","k":"storage","ce":"Local NVMe","cz":"本地 NVMe","eb":"In-node SSDs: lowest latency and fast, good for dataset caching and scratch, but not shared and data may be lost on node failure.","zb":"节点内 SSD：延迟最低、速度快，适合数据集缓存和临时文件，但不在节点间共享，节点故障数据可能丢失。"},{"en":"Parallel file system","zh":"并行文件系统","k":"storage","ce":"Parallel file system","cz":"并行文件系统","eb":"Stripes data across many storage servers that clients access in parallel for high aggregate bandwidth. Examples: Lustre, IBM Storage Scale (GPFS), WEKA, VAST, DDN.","zb":"数据条带化分布在多台存储服务器，客户端并行访问，提供高聚合带宽。例：Lustre、IBM Storage Scale (GPFS)、WEKA、VAST、DDN。"},{"en":"Object storage","zh":"对象存储","k":"storage","ce":"Object storage","cz":"对象存储","eb":"S3-compatible, large capacity, low cost, easy to scale, higher latency. For data lakes, raw data, archives, model artifacts.","zb":"S3 兼容，容量大、成本低、易扩展，延迟较高。用于数据湖、原始数据、归档、模型制品。"},{"en":"NFS limits","zh":"NFS 的局限","k":"storage","ce":"NFS","cz":"网络文件系统","eb":"Traditional network file system; fine for home directories, code, and configs, but often a bottleneck under large-scale concurrent training I/O.","zb":"传统网络文件系统，适合家目录、代码和配置；大规模并发训练 IO 下容易成为瓶颈。"},{"en":"Checkpoint pressure","zh":"Checkpoint 写入压力","k":"storage","ce":"Checkpoint pressure on storage","cz":"Checkpoint 对存储的压力","eb":"Large-model checkpoints can reach several TB and training may pause while writing; low write bandwidth stretches these stalls.","zb":"大模型 checkpoint 可达数 TB，写入期间训练可能暂停；写带宽不足会显著拉长停顿时间。"},{"en":"Data loader bottleneck","zh":"数据加载瓶颈","k":"storage","ce":"Symptoms of a data loader bottleneck","cz":"数据加载瓶颈的症状","eb":"Low, fluctuating GPU utilization; high CPU iowait; unstable step time.","zb":"GPU 利用率低、波动，CPU iowait 高，step 时间不稳定。"},{"en":"Fixes","zh":"瓶颈对策","k":"storage","ce":"Fixes for a data loading bottleneck","cz":"数据加载瓶颈的对策","eb":"Parallel file system, local NVMe caching, GPUDirect Storage, more DataLoader workers, DALI preprocessing on GPU, prefetching.","zb":"并行文件系统、本地 NVMe 缓存、GPUDirect Storage、增加 DataLoader worker、DALI 在 GPU 上预处理、数据预取。"},{"en":"Small files problem","zh":"小文件问题","k":"storage","ce":"Small files problem","cz":"小文件问题","eb":"Huge numbers of small files stress metadata and IOPS. Fix: pack into large sharded formats (WebDataset, TFRecord).","zb":"海量小文件导致元数据压力大、IOPS 瓶颈。对策：打包成大文件分片格式（WebDataset、TFRecord 等）。"}]},{"en":"Data Center","zh":"机房","c":[{"en":"PUE","zh":"电能使用效率","k":"datacenter","ce":"PUE formula","cz":"PUE 公式","eb":"PUE = total facility power ÷ IT equipment power. Ideal is 1.0; lower is better.","zb":"PUE = 数据中心总功耗 ÷ IT 设备功耗。理想值 1.0，越低越好。"},{"en":"PUE example","zh":"PUE 计算例","k":"datacenter","ce":"PUE worked example","cz":"PUE 计算例","eb":"Total 1.5 MW, IT 1.2 MW → PUE = 1.25; every 1 W of IT load costs 0.25 W extra in cooling, power distribution, etc.","zb":"总 1.5 MW、IT 1.2 MW → PUE = 1.25；即每 1 W IT 负载额外消耗 0.25 W 在制冷、配电等。"},{"en":"Rack power density","zh":"机柜功率密度","k":"datacenter","ce":"Typical rack power density","cz":"典型机柜功率密度","eb":"Traditional racks ≈ 5–15 kW. AI racks: air-cooled DGX ≈ 40 kW/rack, liquid-cooled NVL72 ≈ 120 kW class.","zb":"传统机柜约 5–15 kW/柜。AI 机柜：风冷 DGX 约 40 kW/柜，液冷 NVL72 约 120 kW 级。"},{"en":"Hot / cold aisle","zh":"冷热通道","k":"datacenter","ce":"Hot aisle / cold aisle","cz":"冷热通道","eb":"Racks face each other: cold aisles feed cold air to server fronts; hot aisles collect hot exhaust from the backs.","zb":"机柜面对面排列：冷通道送冷风进服务器前面板，热通道收集后部热风。"},{"en":"Containment","zh":"通道封闭","k":"datacenter","ce":"Aisle containment","cz":"冷/热通道封闭","eb":"Doors and roof panels enclose an aisle to stop hot and cold air mixing, improving cooling efficiency and PUE.","zb":"用门和顶板封闭通道，防止冷热风混合，提高制冷效率、降低 PUE。"},{"en":"Direct-to-chip liquid","zh":"冷板液冷","k":"datacenter","ce":"Direct-to-chip liquid cooling","cz":"冷板式液冷","eb":"Coolant flows through cold plates on GPUs/CPUs to carry heat away directly. Required for high-density systems like GB200 NVL72.","zb":"冷却液流过贴在 GPU/CPU 上的冷板直接带走热量。GB200 NVL72 等高密度系统必须使用。"},{"en":"N / N+1 / 2N","zh":"冗余等级","k":"datacenter","ce":"N / N+1 / 2N redundancy","cz":"N / N+1 / 2N 冗余","eb":"N: just enough; N+1: one extra spare; 2N: two complete independent systems.","zb":"N：刚好够用；N+1：额外一个备用；2N：完整双套独立系统。"},{"en":"UPS & PDU","zh":"UPS 与 PDU","k":"datacenter","ce":"Uninterruptible Power Supply (UPS)","cz":"不间断电源","eb":"Bridges short outages and filters power fluctuations until generators start.","zb":"市电中断时短时供电，并过滤电力波动，等待发电机启动。"},{"en":"Planning factors","zh":"规划要素","k":"datacenter","ce":"Data center planning factors","cz":"数据中心规划要考虑的因素","eb":"Power capacity, cooling method, power density, floor load, cabling (lengths/transceivers), space, redundancy, lead time, expandability.","zb":"供电容量、散热方式、功率密度、承重、网络布线（线缆长度/光模块）、空间、冗余、交付周期、扩展性。"}]},{"en":"Deployment Choices","zh":"部署选择","c":[{"en":"DGX BasePOD","zh":"入门参考架构","k":"deploy","ce":"DGX BasePOD","cz":"","eb":"Reference architecture of DGX systems + networking + storage at smaller scale; an enterprise starting point.","zb":"基于 DGX 系统 + 网络 + 存储的参考架构，规模较小，适合企业起步。"},{"en":"DGX SuperPOD","zh":"大规模交钥匙方案","k":"deploy","ce":"DGX SuperPOD","cz":"","eb":"Turnkey large-scale AI data center solution: DGX systems, IB/Spectrum-X compute fabric, certified storage, management software, expert services.","zb":"交钥匙的大规模 AI 数据中心方案：DGX 系统、IB/Spectrum-X 计算网络、认证存储、管理软件、专家服务。"},{"en":"Scalable Unit = 32 DGX","zh":"SU = 32 台 DGX","k":"deploy","ce":"Scalable Unit (SU)","cz":"可扩展单元","eb":"Standard building block of a SuperPOD. DGX H100 SuperPOD: 1 SU = 32 DGX systems (256 GPUs).","zb":"SuperPOD 的标准构建块。DGX H100 SuperPOD：1 SU = 32 台 DGX（256 GPU）。"},{"en":"On-prem pros","zh":"本地部署优点","k":"deploy","ce":"On-premises pros","cz":"本地部署的优点","eb":"Lower TCO at sustained high utilization, data sovereignty and compliance, full control, predictable performance.","zb":"长期高利用率下 TCO 低、数据主权与合规、完全掌控、性能可预期。"},{"en":"Cloud pros","zh":"云的优点","k":"deploy","ce":"Cloud pros","cz":"云的优点","eb":"Pay as you go (OpEx), elastic scaling, fast start, no facilities needed, access to the latest hardware.","zb":"按需付费（OpEx）、弹性扩缩、启动快、无需机房、可试用最新硬件。"},{"en":"CapEx vs OpEx","zh":"资本支出 vs 运营支出","k":"deploy","ce":"CapEx vs OpEx","cz":"资本支出 vs 运营支出","eb":"CapEx: one-time capital spend (buying hardware). OpEx: ongoing operating spend (cloud usage, power, staff).","zb":"CapEx：一次性资本支出（买硬件）；OpEx：持续运营支出（云按需付费、电费、人力）。"},{"en":"Hybrid / bursting","zh":"混合部署","k":"deploy","ce":"Hybrid deployment","cz":"混合部署","eb":"Baseline workloads on-prem, peaks burst to cloud; or training in one place and inference in another.","zb":"基础负载在本地，高峰溢出（cloud bursting）到云；或训练在一处、推理在另一处。"},{"en":"TCO","zh":"总拥有成本","k":"deploy","ce":"Total Cost of Ownership (TCO)","cz":"总拥有成本","eb":"Purchase + facilities + power + cooling + network + ops staff + software licenses + depreciation.","zb":"采购 + 机房 + 电力 + 散热 + 网络 + 运维人力 + 软件授权 + 折旧的总成本。"},{"en":"Edge scenarios","zh":"边缘场景","k":"deploy","ce":"Edge deployment scenarios","cz":"边缘部署场景","eb":"Low latency, limited bandwidth, offline operation, privacy (factory inspection, retail, autonomous driving, medical devices).","zb":"低延迟、带宽受限、离线运行、隐私（工厂质检、零售、自动驾驶、医疗设备）。"}]}],"d":2,"w":"40%"},{"en":"AI Operations","zh":"AI 运维","c":[{"en":"nvidia-smi & NVML","zh":"nvidia-smi 与 NVML","c":[{"en":"NVML","zh":"管理库","k":"nvidia-smi","ce":"NVML","cz":"NVIDIA 管理库","eb":"NVIDIA Management Library: the C management API provided by the driver. nvidia-smi, DCGM, and other monitoring tools build on it.","zb":"NVIDIA Management Library：驱动提供的 C 管理接口。nvidia-smi、DCGM、各类监控工具都基于它。"},{"en":"Default output","zh":"默认输出看什么","k":"nvidia-smi","ce":"What to read in default nvidia-smi output","cz":"nvidia-smi 默认输出看什么","eb":"Driver version, highest CUDA version the driver supports, per-GPU temperature/power/memory/utilization, ECC, processes using the GPU.","zb":"驱动版本、驱动支持的最高 CUDA 版本、每卡温度/功耗/显存/利用率、ECC、占用 GPU 的进程。"},{"en":"\"CUDA Version\" meaning","zh":"CUDA Version 的含义","k":"nvidia-smi","ce":"\"CUDA Version\" in nvidia-smi","cz":"nvidia-smi 里的 “CUDA Version”","eb":"The highest CUDA version the driver supports — not the installed CUDA Toolkit version.","zb":"驱动支持的最高 CUDA 版本，不是已安装的 CUDA Toolkit 版本。"},{"en":"-q -d PERFORMANCE","zh":"降频原因","k":"nvidia-smi","ce":"nvidia-smi -q -d PERFORMANCE","cz":"","eb":"Shows clock throttle (clocks event) reasons: thermal, power cap, hardware slowdown, etc.","zb":"查看时钟降频原因（Clocks Event / Throttle Reasons）：温度、功耗上限、硬件 slowdown 等。"},{"en":"topo -m","zh":"拓扑矩阵","k":"nvidia-smi","ce":"Which command shows GPU/NIC connection topology?","cz":"用哪个命令查看 GPU、网卡之间的连接拓扑？","eb":"nvidia-smi topo -m: prints the NV#/PIX/PXB/PHB/NODE/SYS matrix and CPU/NUMA affinity.","zb":"nvidia-smi topo -m：输出 NV#/PIX/PXB/PHB/NODE/SYS 矩阵和 CPU/NUMA 亲和性。"},{"en":"Persistence mode","zh":"持久模式","k":"nvidia-smi","ce":"nvidia-smi -pm 1","cz":"","eb":"Enables persistence mode (Linux) to keep the driver initialized and cut job start latency. The nvidia-persistenced daemon is preferred.","zb":"开启持久模式（Linux），保持驱动初始化，降低作业启动延迟。推荐改用 nvidia-persistenced 守护进程。"},{"en":"Compute mode","zh":"计算模式","k":"nvidia-smi","ce":"nvidia-smi -c (compute mode)","cz":"nvidia-smi -c（计算模式）","eb":"DEFAULT: shared by many processes; EXCLUSIVE_PROCESS: only one process may use the GPU; PROHIBITED: no compute.","zb":"DEFAULT：多进程共享；EXCLUSIVE_PROCESS：只允许一个进程使用 GPU；PROHIBITED：禁止计算。"},{"en":"utilization.gpu caveat","zh":"利用率的局限","k":"nvidia-smi","ce":"What utilization.gpu really means","cz":"utilization.gpu 的真实含义","eb":"Fraction of the sample period in which any kernel was running. 100% does not mean all SMs are fully busy.","zb":"采样周期内有任何 kernel 在执行的时间比例。100% 不代表所有 SM 都在满负荷工作。"},{"en":"CUDA_VISIBLE_DEVICES","zh":"可见 GPU","k":"nvidia-smi","ce":"CUDA_VISIBLE_DEVICES","cz":"","eb":"Environment variable that limits which GPUs a CUDA app sees (e.g., 0,1) and renumbers them.","zb":"环境变量，限制 CUDA 应用能看到哪些 GPU（如 0,1），并重新编号。"}]},{"en":"DCGM & Monitoring","zh":"DCGM 与监控","c":[{"en":"DCGM","zh":"数据中心 GPU 管理器","k":"dcgm","ce":"Data Center GPU Manager (DCGM)","cz":"数据中心 GPU 管理器","eb":"Data center GPU management suite: health monitoring, active diagnostics, policy alerts, job statistics, telemetry, at cluster scale.","zb":"数据中心 GPU 管理套件：健康监控、主动诊断、策略告警、作业统计、遥测，可在集群规模使用。"},{"en":"DCGM vs nvidia-smi","zh":"两者区别","k":"dcgm","ce":"DCGM vs nvidia-smi","cz":"DCGM 与 nvidia-smi 的区别","eb":"nvidia-smi is a single-node view/config tool; DCGM targets cluster ops: continuous background monitoring, diagnostics, policies, job-level stats, Prometheus/K8s integration.","zb":"nvidia-smi 是单机查看/配置工具；DCGM 面向集群运维：后台持续监控、诊断、策略、作业级统计、与 Prometheus/K8s 集成。"},{"en":"dcgmi diag -r 1","zh":"快速诊断（秒级）","k":"dcgm","ce":"dcgmi diag -r 1","cz":"","eb":"Quick diagnostic (seconds): basic deployment and software checks; run before every job.","zb":"快速诊断（秒级）：基本部署和软件检查，适合每个作业前跑。"},{"en":"dcgmi diag -r 3","zh":"长诊断（数十分钟）","k":"dcgm","ce":"dcgmi diag -r 3","cz":"","eb":"Long diagnostic (tens of minutes): memory, compute stress, bandwidth, power; for acceptance testing or post-failure investigation.","zb":"长诊断（数十分钟级）：显存、计算压力、带宽、功耗等全面测试，用于上线验收或故障后排查。"},{"en":"DCGM Exporter :9400","zh":"Prometheus 导出器","k":"dcgm","ce":"DCGM Exporter","cz":"","eb":"Exposes DCGM metrics in Prometheus format (default port 9400, /metrics); often deployed by the GPU Operator.","zb":"把 DCGM 指标以 Prometheus 格式暴露（默认端口 9400，路径 /metrics），常由 GPU Operator 部署。"},{"en":"Exporter → Prometheus → Grafana","zh":"监控链路","k":"dcgm","ce":"Standard GPU monitoring pipeline","cz":"GPU 监控标准链路","eb":"DCGM Exporter → Prometheus (scrape/store/alert) → Grafana (dashboards); alerts go out through Alertmanager.","zb":"DCGM Exporter → Prometheus（抓取/存储/告警）→ Grafana（仪表盘）；告警经 Alertmanager 发出。"},{"en":"SM_ACTIVE","zh":"SM 活跃度","k":"dcgm","ce":"DCGM_FI_PROF_SM_ACTIVE","cz":"","eb":"SM activity: fraction of time at least one warp is resident on an SM; reflects real load better than GPU_UTIL.","zb":"SM 活跃度：至少有一个 warp 在 SM 上的时间比例，比 GPU_UTIL 更能反映实际负载。"},{"en":"Tensor pipe active","zh":"Tensor Core 活跃度","k":"dcgm","ce":"DCGM_FI_PROF_PIPE_TENSOR_ACTIVE","cz":"","eb":"Tensor Core pipe activity; shows whether mixed-precision math is actually using Tensor Cores.","zb":"Tensor Core 管线活跃度，反映混合精度矩阵运算是否在用 Tensor Core。"},{"en":"Metrics to watch","zh":"应监控的指标","k":"dcgm","ce":"GPU metrics you should monitor","cz":"应该监控的 GPU 指标","eb":"Utilization and SM Active, memory, temperature, power, clocks and throttle reasons, ECC/row remapping, XIDs, PCIe/NVLink throughput and errors.","zb":"利用率与 SM Active、显存、温度、功耗、时钟与降频原因、ECC/行重映射、XID、PCIe/NVLink 吞吐与错误。"},{"en":"Where DCGM works","zh":"DCGM 适用环境","k":"dcgm","ce":"Where DCGM works","cz":"DCGM 适用环境","eb":"Data center GPUs with native Linux drivers. Tested in this repo: on a consumer GPU + WSL2, DCGM Exporter starts but collects no metrics.","zb":"数据中心 GPU + 原生 Linux 驱动。本仓库实测：消费卡 + WSL2 上 DCGM Exporter 能启动但采不到指标。"}]},{"en":"XID & ECC","zh":"XID 与 ECC","c":[{"en":"XID errors","zh":"XID 错误","k":"xid","ce":"XID errors","cz":"XID 错误","eb":"GPU error codes the NVIDIA driver writes to the kernel log; view with dmesg or journalctl -k, e.g., \"NVRM: Xid ... 79\".","zb":"NVIDIA 驱动写入内核日志的 GPU 错误编号，用 dmesg 或 journalctl -k 查看，格式如 “NVRM: Xid ... 79”。"},{"en":"Xid 13 / 31 · app","zh":"应用问题","k":"xid","ce":"Xid 13","cz":"","eb":"Graphics Engine Exception: usually an application problem (out-of-bounds access, illegal instruction); check the code and driver version first.","zb":"Graphics Engine Exception：多为应用程序问题（越界访问、非法指令），先查代码和驱动版本。"},{"en":"Xid 48 · DBE","zh":"双比特 ECC","k":"xid","ce":"Xid 48","cz":"","eb":"Double-bit ECC error (DBE, uncorrectable): drain the node, reset the GPU, check row remapping/page retirement; RMA if it recurs.","zb":"双比特 ECC 错误（DBE，不可纠正）：隔离节点、重置 GPU、检查行重映射/页退役，反复出现则 RMA。"},{"en":"Xid 74 · NVLink","zh":"NVLink 错误","k":"xid","ce":"Xid 74","cz":"","eb":"NVLink error: check NVLink status and connections, reset; persistent errors need hardware investigation.","zb":"NVLink 错误：检查 NVLink 状态和线缆/连接器，重置；持续出现需硬件排查。"},{"en":"Xid 79 · off the bus","zh":"GPU 掉线","k":"xid","ce":"Xid 79","cz":"","eb":"GPU has fallen off the bus: severe. Drain the node, check PCIe, power, and cooling; reboot, reseat, or RMA.","zb":"GPU 从总线掉线（fallen off the bus）：严重。隔离节点，检查 PCIe、供电、散热，重启、重新插拔或 RMA。"},{"en":"Xid 94 / 95","zh":"隔离 / 未隔离 ECC","k":"xid","ce":"Xid 95","cz":"","eb":"Uncontained ECC error: requires a GPU reset (A100+).","zb":"未被隔离的（uncontained）ECC 错误：需要重置 GPU（A100+）。"},{"en":"SBE vs DBE","zh":"单比特 vs 双比特","k":"xid","ce":"SBE vs DBE","cz":"单比特错误 vs 双比特错误","eb":"Single-bit errors (SBE) are corrected automatically; double-bit errors (DBE) are uncorrectable and make applications fail.","zb":"单比特错误（SBE）可自动纠正；双比特错误（DBE）不可纠正，会导致应用出错。"},{"en":"Row remapping","zh":"行重映射","k":"xid","ce":"Row remapping","cz":"行重映射","eb":"A100 and later: replaces faulty memory rows with spare rows, usually effective after a GPU reset.","zb":"A100 及以后：用备用行替换出错的显存行，通常在 GPU 重置后生效。"},{"en":"Don't disable ECC","zh":"不要关闭 ECC","k":"xid","ce":"Does disabling ECC fix ECC errors?","cz":"关闭 ECC 能解决 ECC 错误吗","eb":"No. Disabling ECC only hides errors and leads to silent data corruption.","zb":"不能。关闭 ECC 只会掩盖错误，导致静默数据损坏。"},{"en":"Fault workflow","zh":"故障处理流程","k":"xid","ce":"Standard hardware fault workflow","cz":"硬件故障标准处理流程","eb":"Detect → isolate (drain, no new jobs) → diagnose (dcgmi diag, logs) → fix/reset/RMA → verify → return to service → document.","zb":"发现 → 隔离（drain，不再调度新作业）→ 诊断（dcgmi diag、日志）→ 修复/重置/RMA → 验证 → 恢复上线 → 记录。"}]},{"en":"Slurm","zh":"Slurm 调度","c":[{"en":"Slurm","zh":"HPC 调度器","k":"slurm","ce":"Slurm","cz":"","eb":"Open-source HPC job scheduler/resource manager, the most common on AI training clusters; strong at batch, multi-node jobs, queues, and fair share.","zb":"开源 HPC 作业调度器/资源管理器，AI 训练集群最常用，擅长批处理、多节点作业、队列和公平共享。"},{"en":"sbatch / srun / salloc","zh":"提交与运行","k":"slurm","ce":"sbatch","cz":"","eb":"Submits a batch script; the job waits in the queue for scheduling.","zb":"提交批处理脚本，作业进入队列等待调度。"},{"en":"squeue","zh":"作业队列","k":"slurm","ce":"squeue","cz":"","eb":"Shows the job queue and job states (PD pending, R running, etc.).","zb":"查看作业队列和作业状态（PD 排队、R 运行等）。"},{"en":"sinfo","zh":"节点状态","k":"slurm","ce":"sinfo","cz":"","eb":"Shows partition and node states (idle, alloc, mix, drain, down).","zb":"查看分区和节点状态（idle、alloc、mix、drain、down）。"},{"en":"--gres=gpu:N","zh":"申请 GPU","k":"slurm","ce":"How to request GPUs in Slurm","cz":"Slurm 申请 GPU 的写法","eb":"--gres=gpu:4 or --gpus=4, --gpus-per-node=8.","zb":"--gres=gpu:4 或 --gpus=4、--gpus-per-node=8。"},{"en":"drain a node","zh":"隔离节点","k":"slurm","ce":"How to remove a node from scheduling","cz":"如何把节点隔离出调度","eb":"scontrol update nodename=<node> state=drain reason=\"...\"; after repair, state=resume.","zb":"scontrol update nodename=<节点> state=drain reason=\"原因\"；修复后 state=resume。"},{"en":"Fair-share","zh":"公平共享","k":"slurm","ce":"Fair-share","cz":"公平共享","eb":"Adjusts priority by each user's/account's historical usage; heavy users get lower priority.","zb":"根据用户/账户的历史使用量调整优先级，用得多的优先级降低。"},{"en":"Backfill","zh":"回填调度","k":"slurm","ce":"Backfill scheduling","cz":"回填调度","eb":"Fills idle resources with small jobs without delaying higher-priority jobs, raising utilization.","zb":"在不推迟高优先级作业的前提下，用小作业填充空闲资源，提高利用率。"},{"en":"Prolog health check","zh":"作业前检查","k":"slurm","ce":"Prolog / Epilog","cz":"作业前 / 作业后脚本","eb":"Scripts run on nodes before a job starts / after it ends; used for health checks (e.g., dcgmi diag -r 1) and cleanup.","zb":"作业开始前 / 结束后在节点上执行的脚本，常用于健康检查（如 dcgmi diag -r 1）和清理。"},{"en":"Pyxis + Enroot","zh":"Slurm 跑容器","k":"slurm","ce":"Pyxis + Enroot","cz":"","eb":"Enroot turns container images into unprivileged sandboxes; Pyxis is a Slurm plugin enabling srun --container-image=nvcr.io#nvidia/pytorch:xx.xx-py3.","zb":"Enroot：把容器镜像转为非特权沙箱运行；Pyxis：Slurm 插件，支持 srun --container-image=nvcr.io#nvidia/pytorch:xx.xx-py3。"}]},{"en":"Kubernetes","zh":"Kubernetes 编排","c":[{"en":"Slurm vs Kubernetes","zh":"怎么选","k":"k8s","ce":"Slurm vs Kubernetes: how to choose","cz":"Slurm 与 Kubernetes 怎么选","eb":"Tightly coupled multi-node training, batch, fair share → Slurm. Inference microservices, autoscaling, rolling updates, cloud native → Kubernetes.","zb":"多节点紧耦合训练、批处理、公平共享 → Slurm；推理微服务、自动扩缩、滚动更新、云原生 → Kubernetes。"},{"en":"nvidia.com/gpu","zh":"GPU 扩展资源","k":"k8s","ce":"nvidia.com/gpu","cz":"","eb":"Extended resource registered by the NVIDIA device plugin; pods request whole GPUs in resources.limits.","zb":"NVIDIA Device Plugin 注册的扩展资源名，Pod 在 resources.limits 中申请整数个 GPU。"},{"en":"Device plugin","zh":"设备插件","k":"k8s","ce":"NVIDIA device plugin","cz":"NVIDIA 设备插件","eb":"DaemonSet that registers nvidia.com/gpu with the kubelet and assigns specific GPUs when pods start.","zb":"DaemonSet，向 kubelet 注册 nvidia.com/gpu 资源，并在 Pod 启动时分配具体 GPU。"},{"en":"GPU Operator","zh":"GPU Operator","k":"k8s","ce":"NVIDIA GPU Operator","cz":"","eb":"Uses the Operator pattern to deploy and manage everything a GPU node needs, making GPU nodes as plug-and-play as CPU nodes.","zb":"用 Operator 自动部署和管理 GPU 节点所需全部组件，让 GPU 节点像 CPU 节点一样即插即用。"},{"en":"Operator components","zh":"Operator 组件","k":"k8s","ce":"Components of the GPU Operator","cz":"GPU Operator 包含哪些组件","eb":"GPU driver container, Container Toolkit, device plugin, GPU Feature Discovery, DCGM/DCGM Exporter, MIG Manager, Node Feature Discovery, validator.","zb":"GPU 驱动容器、Container Toolkit、Device Plugin、GPU Feature Discovery、DCGM/DCGM Exporter、MIG Manager、Node Feature Discovery、Validator。"},{"en":"GPU Feature Discovery","zh":"节点 GPU 标签","k":"k8s","ce":"GPU Feature Discovery (GFD)","cz":"GPU 特性发现","eb":"Labels nodes with GPU properties: model (nvidia.com/gpu.product), memory, count, MIG config, CUDA driver version.","zb":"给节点打 GPU 标签：型号（nvidia.com/gpu.product）、显存、数量、MIG 配置、CUDA 驱动版本。"},{"en":"Network Operator","zh":"网络 Operator","k":"k8s","ce":"NVIDIA Network Operator","cz":"","eb":"Deploys high-speed networking in K8s: NIC drivers (OFED), RDMA device plugin, SR-IOV, modules needed for GPUDirect RDMA.","zb":"在 K8s 中部署高速网络组件：网卡驱动（OFED）、RDMA 设备插件、SR-IOV、GPUDirect RDMA 所需模块。"},{"en":"MIG single vs mixed","zh":"MIG 策略","k":"k8s","ce":"MIG strategies in K8s: single vs mixed","cz":"K8s 中 MIG 的 single 与 mixed 策略","eb":"single: all MIG instances on a node share one profile and appear as nvidia.com/gpu; mixed: each profile is its own resource, e.g., nvidia.com/mig-1g.10gb.","zb":"single：节点上所有 MIG 实例同规格，仍以 nvidia.com/gpu 暴露；mixed：不同规格分别暴露为 nvidia.com/mig-1g.10gb 等资源。"},{"en":"Run:ai / KAI","zh":"AI 工作负载调度","k":"k8s","ce":"Run:ai","cz":"","eb":"NVIDIA-acquired K8s AI workload orchestration: GPU quotas, fractional GPUs, queues, fair share, dynamic scheduling.","zb":"NVIDIA 收购的 K8s AI 工作负载编排平台：GPU 配额、分数 GPU、队列、公平共享、动态调度。"},{"en":"Base Command Manager","zh":"集群管理","k":"k8s","ce":"Base Command Manager (BCM)","cz":"","eb":"Cluster management software (formerly Bright Cluster Manager): bare-metal provisioning, OS images, Slurm/K8s deployment, monitoring, user management.","zb":"集群管理软件（原 Bright Cluster Manager）：裸机部署、OS 镜像、Slurm/K8s 部署、监控、用户管理。"},{"en":"Mission Control","zh":"AI 工厂运维","k":"k8s","ce":"NVIDIA Mission Control","cz":"","eb":"AI factory operations stack: combines cluster management (BCM), workload scheduling (Run:ai/Slurm), health monitoring, and automated failure recovery.","zb":"AI 工厂运维软件栈：整合集群管理（BCM）、工作负载调度（Run:ai/Slurm）、健康监控与自动故障恢复。"}]},{"en":"GPU Sharing","zh":"GPU 共享与虚拟化","c":[{"en":"Five ways","zh":"五种方式","k":"sharing","ce":"Five ways to share GPUs","cz":"GPU 共享的五种方式","eb":"PCIe passthrough, NVIDIA vGPU, MIG, time-slicing, MPS.","zb":"PCIe 直通、NVIDIA vGPU、MIG、时间片（time-slicing）、MPS。"},{"en":"PCIe passthrough","zh":"整卡直通","k":"sharing","ce":"PCIe passthrough","cz":"GPU 直通","eb":"Assigns a whole physical GPU directly to one VM; near bare-metal performance but one GPU per VM.","zb":"把整张物理 GPU 直接分配给一个虚拟机，接近裸机性能，但一张卡只能给一个 VM。"},{"en":"NVIDIA vGPU","zh":"多 VM 共享（需授权）","k":"sharing","ce":"NVIDIA vGPU","cz":"","eb":"Shares one GPU among multiple VMs on a hypervisor (e.g., VMware vSphere); requires vGPU software and a license.","zb":"在 hypervisor（如 VMware vSphere）上把一张 GPU 分给多个虚拟机共享；需要 vGPU 软件和授权（license）。"},{"en":"MIG","zh":"硬件切分（最多 7）","k":"sharing","ce":"Multi-Instance GPU (MIG)","cz":"多实例 GPU","eb":"Partitions one GPU in hardware into up to 7 instances, each with its own SMs, L2 cache, memory, and bandwidth: hardware isolation and QoS.","zb":"把一张 GPU 硬件切分成最多 7 个独立实例，每个有独立的 SM、L2 缓存、显存和带宽，硬件级隔离与 QoS。"},{"en":"MIG profiles (A100 40GB)","zh":"MIG 规格","k":"sharing","ce":"MIG profiles on A100 40GB","cz":"A100 40GB 的 MIG 规格","eb":"1g.5gb (up to 7), 2g.10gb, 3g.20gb, 4g.20gb, 7g.40gb.","zb":"1g.5gb（最多 7 个）、2g.10gb、3g.20gb、4g.20gb、7g.40gb。"},{"en":"Time-slicing","zh":"时间片（无隔离）","k":"sharing","ce":"Time-slicing","cz":"时间片","eb":"Multiple processes/containers take turns on the whole GPU; simple and works on any GPU, but no memory or fault isolation.","zb":"多个进程/容器轮流使用整张 GPU；配置简单、任何 GPU 可用，但没有显存隔离和故障隔离。"},{"en":"MPS","zh":"多进程并发","k":"sharing","ce":"Multi-Process Service (MPS)","cz":"多进程服务","eb":"Lets kernels from multiple CUDA processes run concurrently on one GPU to raise utilization for small jobs; can cap SM share, but memory/fault isolation is limited.","zb":"让多个 CUDA 进程的 kernel 并发跑在同一 GPU 上，提高小任务利用率；可限制 SM 比例，但显存/故障隔离有限。"},{"en":"Isolation ranking","zh":"隔离强度排序","k":"sharing","ce":"Isolation strength from strongest to weakest","cz":"隔离强度从强到弱","eb":"Passthrough (exclusive) ≈ MIG (hardware partition) > time-sliced vGPU > MPS > time-slicing (no isolation).","zb":"直通（独占）≈ MIG（硬件分区）> vGPU 时间片 > MPS > 时间片（无隔离）。"}]},{"en":"Containers","zh":"容器","c":[{"en":"Container Toolkit","zh":"容器 GPU 支持","k":"containers","ce":"NVIDIA Container Toolkit","cz":"NVIDIA 容器工具包","eb":"Lets Docker, containerd, CRI-O, etc. access GPUs by injecting GPU devices and driver libraries at container start.","zb":"让 Docker、containerd、CRI-O 等容器运行时访问 GPU：在容器启动时注入 GPU 设备和驱动库。"},{"en":"--gpus all","zh":"请求 GPU","k":"containers","ce":"docker run --gpus all","cz":"","eb":"Requests all GPUs for the container; or --gpus '\"device=0,1\"' to pick specific ones.","zb":"请求把所有 GPU 交给容器；也可 --gpus '\"device=0,1\"' 指定。"},{"en":"Without --gpus","zh":"不加 --gpus 的后果","k":"containers","ce":"What happens without --gpus","cz":"不加 --gpus 的后果","eb":"The container has no GPU devices and no nvidia-smi: \"executable file not found\" (incident 01 in this repo).","zb":"容器里没有 GPU 设备和 nvidia-smi，报 executable file not found（本仓库故障记录 01）。"},{"en":"Host needs only driver","zh":"宿主机只需驱动","k":"containers","ce":"What must be installed on the host","cz":"宿主机需要装什么","eb":"Only the NVIDIA driver + Container Toolkit. CUDA Toolkit, cuDNN, and frameworks live in the container image.","zb":"只需要 NVIDIA 驱动 + Container Toolkit。CUDA Toolkit、cuDNN、框架都在容器镜像里。"},{"en":"Driver backward compatible","zh":"驱动向后兼容","k":"containers","ce":"CUDA driver backward compatibility","cz":"CUDA 驱动向后兼容","eb":"Newer drivers run applications built with older CUDA versions.","zb":"新驱动可以运行用旧 CUDA 版本构建的应用。"},{"en":"Container CUDA too new","zh":"容器 CUDA 太新","k":"containers","ce":"Container CUDA newer than the driver","cz":"容器 CUDA 比驱动新会怎样","eb":"Fails with \"CUDA driver version is insufficient\". Fix: upgrade the host driver; data center GPUs can also use the CUDA forward compatibility package.","zb":"报 “CUDA driver version is insufficient”。解决：升级宿主机驱动；数据中心卡也可用 CUDA forward compatibility 包。"},{"en":"NGC containers","zh":"NGC 容器优势","k":"containers","ce":"Advantages of NGC containers","cz":"NGC 容器的优势","eb":"Monthly, tested, performance-tuned combinations of framework + CUDA + libraries from NVIDIA, reducing dependency conflicts.","zb":"NVIDIA 每月发布、经过测试与性能调优的框架 + CUDA + 库组合，减少依赖冲突。"}]},{"en":"Ops & Troubleshooting","zh":"运维与排障","c":[{"en":"Burn-in","zh":"上线验收","k":"ops","ce":"Cluster acceptance (burn-in)","cz":"集群上线验收","eb":"Before handover, run long stress and diagnostics: dcgmi diag -r 3, NCCL tests, HPL, storage tests, to confirm performance and stability.","zb":"交付前跑长时间压力和诊断：dcgmi diag -r 3、NCCL 测试、HPL、存储压测，确认性能和稳定性达标。"},{"en":"Version baseline","zh":"版本基线","k":"ops","ce":"Version baseline","cz":"版本基线","eb":"Standardize OS, kernel, GPU driver, CUDA, firmware (GPU, NIC, BMC), OFED, and container runtime to avoid \"snowflake\" nodes.","zb":"统一 OS、内核、GPU 驱动、CUDA、固件（GPU、网卡、BMC）、OFED、容器运行时版本，避免“雪花节点”。"},{"en":"Rolling upgrade","zh":"滚动升级","k":"ops","ce":"Rolling upgrade","cz":"滚动升级","eb":"Drain nodes in batches → upgrade driver/firmware → verify → resume, keeping the cluster available throughout.","zb":"分批 drain 节点 → 升级驱动/固件 → 验证 → 恢复，保证集群整体持续可用。"},{"en":"Pre-job health checks","zh":"作业前健康检查","k":"ops","ce":"Pre-job health checks","cz":"作业前健康检查","eb":"Run quick checks in Slurm Prolog or a K8s init container (dcgmi diag -r 1, NVLink/IB state) and isolate bad nodes automatically.","zb":"在 Slurm Prolog 或 K8s init 容器中跑快速检查（dcgmi diag -r 1、NVLink/IB 状态），有问题自动隔离节点。"},{"en":"Driver not loaded","zh":"驱动无法通信","k":"ops","ce":"Symptom: nvidia-smi can't communicate with the driver","cz":"症状：nvidia-smi 报无法与驱动通信","eb":"Check the driver module is loaded (lsmod | grep nvidia), DKMS rebuilt it after a kernel upgrade, Secure Boot isn't blocking it.","zb":"检查驱动模块是否加载（lsmod | grep nvidia）、内核升级后 DKMS 是否重编译、Secure Boot 是否阻止加载。"},{"en":"Slow multi-node","zh":"多节点训练慢","k":"ops","ce":"Symptom: slow multi-node training","cz":"症状：多节点训练慢","eb":"NCCL_DEBUG=INFO to see if NET/IB is used; nccl-tests for busbw; check IB port speed, topology, GPUDirect RDMA, congestion.","zb":"NCCL_DEBUG=INFO 看是否走 NET/IB；用 nccl-tests 测 busbw；检查 IB 端口速率、拓扑、GPUDirect RDMA、拥塞。"},{"en":"NCCL NET/Socket","zh":"NCCL 回退 TCP","k":"ops","ce":"NCCL falls back to NET/Socket — meaning?","cz":"NCCL 回退到 NET/Socket 说明什么","eb":"InfiniBand/RDMA isn't being used; traffic goes over TCP. Check RDMA drivers, NIC state, RDMA devices mounted in the container, NCCL_IB_HCA.","zb":"没有用上 InfiniBand/RDMA，走了 TCP。检查 RDMA 驱动、网卡状态、容器是否挂载 RDMA 设备、NCCL_IB_HCA 设置。"},{"en":"Low util + iowait","zh":"利用率低 + iowait 高","k":"ops","ce":"Symptom: low GPU utilization, high iowait","cz":"症状：GPU 利用率低、iowait 高","eb":"A data loading or storage bottleneck (see the storage deck).","zb":"数据加载或存储瓶颈（见存储牌组）。"},{"en":"CUDA OOM","zh":"显存不足","k":"ops","ce":"Symptom: CUDA out of memory","cz":"症状：CUDA 显存不足","eb":"Smaller batch, mixed precision, gradient accumulation, activation checkpointing, quantization, model parallelism, or check for leftover processes holding memory.","zb":"减小 batch、混合精度、梯度累积、激活重计算、量化、模型并行，或检查是否有残留进程占用显存。"},{"en":"Runbook & postmortem","zh":"运维手册与复盘","k":"ops","ce":"Runbook","cz":"运维手册","eb":"Standard steps for a specific alert or failure so on-call staff can act repeatably (this repo's runbooks/ folder).","zb":"针对特定告警/故障的标准处理步骤，让值班人员可重复执行（本仓库 runbooks/ 目录）。"},{"en":"MTTR / MTBF","zh":"修复与故障间隔","k":"ops","ce":"MTTR / MTBF","cz":"平均修复时间 / 平均故障间隔","eb":"Mean Time To Repair / Mean Time Between Failures. Large-cluster ops aims to cut MTTR and increase productive training time.","zb":"平均修复时间 / 平均故障间隔时间。大集群运维要降低 MTTR、提高有效训练时间。"}]}],"d":3,"w":"22%"}],"sub":"AI Infrastructure & Operations"};
